// ignore: unused_element
class _ProjectedShiftDetailOld extends StatelessWidget {
  final ShiftRecord shift;
  final bool isOpen;
  const _ProjectedShiftDetailOld({required this.shift, required this.isOpen});

  @override
  Widget build(BuildContext context) {
    final statusLabel = isOpen ? 'Open' : 'Projected';
    final headerLabel = isOpen ? 'PLAN CONTEXT' : 'PROJECTED';
    final statusColor = isOpen ? AppColors.sunsetDark : AppColors.textMuted;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Container(
          width: double.infinity,
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
          color: AppColors.backgroundDeep,
          child: Text(
            '${shift.dayLabel} ${shift.daypartLabel} $statusLabel',
            style: AppTextStyles.mono11(color: isOpen ? AppColors.sunsetDark : AppColors.textPrimary),
          ),
        ),
        Padding(
          padding: const EdgeInsets.fromLTRB(14, 10, 14, 13),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [

          // Header
          Row(
            children: [
              Expanded(
                flex: 4,
                child: Text(
                  'METRIC',
                  style: AppTextStyles.mono8(color: AppColors.textMuted),
                ),
              ),
              Expanded(
                flex: 6,
                child: Text(
                  headerLabel,
                  style: AppTextStyles.mono8(color: statusColor),
                  textAlign: TextAlign.right,
                ),
              ),
            ],
          ),
          Container(height: 1, color: AppColors.borderSubtle),
          const SizedBox(height: 7),

          // Covers row
          Row(
            children: [
              Expanded(
                flex: 4,
                child: Text(
                  'Covers',
                  style: AppTextStyles.body13(color: AppColors.textSecondary),
                ),
              ),
              Expanded(
                flex: 6,
                child: Text(
                  '${shift.forecastCovers}  (plan)',
                  style: AppTextStyles.mono12(color: AppColors.sunsetDark),
                  textAlign: TextAlign.right,
                ),
              ),
            ],
          ),
          const SizedBox(height: 7),

          // FOH Hours row
          Row(
            children: [
              Expanded(
                flex: 4,
                child: Text(
                  'FOH Hours',
                  style: AppTextStyles.body13(color: AppColors.textSecondary),
                ),
              ),
              Expanded(
                flex: 6,
                child: Text(
                  '${shift.fohHours}  (plan)',
                  style: AppTextStyles.mono12(color: AppColors.sunsetDark),
                  textAlign: TextAlign.right,
                ),
              ),
            ],
          ),
          const SizedBox(height: 7),

          // BOH Hours row
          Row(
            children: [
              Expanded(
                flex: 4,
                child: Text(
                  'BOH Hours',
                  style: AppTextStyles.body13(color: AppColors.textSecondary),
                ),
              ),
              Expanded(
                flex: 6,
                child: Text(
                  '${shift.bohHours}  (plan)',
                  style: AppTextStyles.mono12(color: AppColors.sunsetDark),
                  textAlign: TextAlign.right,
                ),
              ),
            ],
          ),
          const SizedBox(height: 7),

          // Blended Wage row ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â 7.55q.4: Benchmark-owned, read from
          // current ActiveTargetProfile via the 7.55q.3 shared seam.
          // Honest fallback to per-shift fields when the profile
          // notifier isn't in scope (e.g. legacy widget tests).
          Builder(
            builder: (ctx) {
              final profile = ctx
                  .watch<ActiveTargetProfileNotifier?>()
                  ?.profile;
              final wage =
                  profile?.targetBlendedWage ??
                  shift.snapshotBlendedWage ??
                  shift.blendedWage;
              return Row(
                children: [
                  Expanded(
                    flex: 4,
                    child: Text(
                      'Blended Wage',
                      style: AppTextStyles.body13(
                        color: AppColors.textSecondary,
                      ),
                    ),
                  ),
                  Expanded(
                    flex: 6,
                    child: Text(
                      '\$${wage.toStringAsFixed(2)}  (plan)',
                      style: AppTextStyles.mono12(color: AppColors.sunsetDark),
                      textAlign: TextAlign.right,
                    ),
                  ),
                ],
              );
            },
          ),
          const SizedBox(height: 7),

          // Labor % row ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â 7.55q.4: Benchmark-owned theoretical %,
          // read from current ActiveTargetProfile (Rule 3). Honest
          // fallback to the shift's locked-at-write value when the
          // profile notifier isn't in scope.
          Builder(
            builder: (ctx) {
              final profile = ctx
                  .watch<ActiveTargetProfileNotifier?>()
                  ?.profile;
              final theoPct =
                  profile?.theoreticalLaborPct ?? shift.theoreticalLaborPct;
              return Row(
                children: [
                  Expanded(
                    flex: 4,
                    child: Text(
                      'Labor %',
                      style: AppTextStyles.body13(
                        color: AppColors.textSecondary,
                      ),
                    ),
                  ),
                  Expanded(
                    flex: 6,
                    child: Text(
                      '${theoPct.toStringAsFixed(1)}%  (theoretical)',
                      style: AppTextStyles.mono12(color: AppColors.sunsetDark),
                      textAlign: TextAlign.right,
                    ),
                  ),
                ],
              );
            },
          ),

          const SizedBox(height: 12),

          // Week-end projection line
          Builder(
            builder: (ctx) {
              final wd = ctx.read<WeekDataNotifier>().weekData!;
              final projColor = wd.projVariancePts > 0
                  ? AppColors.negative
                  : AppColors.positive;
              return RichText(
                text: TextSpan(
                  style: AppTextStyles.mono10(color: AppColors.textMuted),
                  children: [
                    const TextSpan(text: 'Week ends at '),
                    TextSpan(
                      text: '${wd.projActualLaborPct.toStringAsFixed(1)}%',
                      style: AppTextStyles.mono10(color: projColor),
                    ),
                    const TextSpan(text: '  ->  gap '),
                    TextSpan(
                      text:
                          '\$${wd.projDollarGapWeekly.abs().toStringAsFixed(0)}',
                      style: AppTextStyles.mono10(color: projColor),
                    ),
                  ],
                ),
              );
            },
          ),

          const SizedBox(height: 4),
          Text(
            isOpen
                ? 'Live shift in progress. Finalizes on close.'
                : 'Projected from weekly plan. Actuals populate when shift closes.',
            style: AppTextStyles.mono8(
              color: isOpen ? AppColors.sunsetDark : AppColors.textMuted,
            ),
          ),
        ],
      ),
        ),
      ],
    );
  }
}

// ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Shift table row (used in expanded closed-shift detail) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

class _ClosedShiftDetail extends StatelessWidget {
  final ShiftRecord shift;
  const _ClosedShiftDetail({required this.shift});

  @override
  Widget build(BuildContext context) {
    final s = shift;

    final lockedPPA = s.lockedTargetPPA;
    final lockedCPLH = s.lockedTargetCPLH;
    final lockedSPLH = s.lockedTargetSPLH;
    final lockedFohWage = s.lockedTargetFohWage;
    final lockedBohWage = s.lockedTargetBohWage;
    final lockedFohPct = s.lockedTheoreticalFohLaborPct;
    final lockedBohPct = s.lockedTheoreticalBohLaborPct;

    final coversDelta = s.covers - s.forecastCovers;
    final ppaDelta = s.ppa - lockedPPA;
    final cplhDelta = s.cplh - lockedCPLH;
    final splhDelta = s.splh - lockedSPLH;

    final theoFoh = s.modelFohHours;
    final theoBoh = s.modelBohHours;
    final totalModelHours = theoFoh + theoBoh;
    final lockedBlendedWage = totalModelHours > 0
        ? (theoFoh * lockedFohWage + theoBoh * lockedBohWage) / totalModelHours
        : 0.0;
    final wageDelta = s.blendedWage - lockedBlendedWage;

    // Daypart label is now rendered by StickyDaypartLabelDelegate.
    // This widget starts directly with the detail rows.
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 10, 14, 13),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _GroupBand('CONDITIONS'),
          _ShiftRow(
            label: 'Covers',
            target: s.forecastCovers.toString(),
            actual: s.covers.toString(),
            variance: Fmt.varStr(coversDelta),
            varColor: Fmt.varColor('Covers', coversDelta.toDouble()),
          ),
          _micro(),
          _ShiftRow(
            label: 'Blended Wage',
            target: '\$${lockedBlendedWage.toStringAsFixed(2)}',
            actual: '\$${s.blendedWage.toStringAsFixed(2)}',
            variance: Fmt.varDollars(wageDelta),
            varColor: Fmt.varColor('Blended Wage', wageDelta),
          ),
          _GroupBand('EXECUTION'),
          _ShiftRow(
            label: 'PPA',
            target: '\$${lockedPPA.toStringAsFixed(2)}',
            actual: '\$${s.ppa.toStringAsFixed(2)}',
            variance: Fmt.varDollars(ppaDelta),
            varColor: Fmt.varColor('PPA', ppaDelta),
          ),
          _micro(),
          _ShiftRow(
            label: 'FOH Hours',
            target: theoFoh.toString(),
            actual: s.fohHours.toString(),
            variance: Fmt.varStr(s.fohHours - theoFoh),
            varColor: Fmt.varColor(
              'FOH Hours',
              (s.fohHours - theoFoh).toDouble(),
            ),
          ),
          _micro(),
          _ShiftRow(
            label: 'BOH Hours',
            target: theoBoh.toString(),
            actual: s.bohHours.toString(),
            variance: Fmt.varStr(s.bohHours - theoBoh),
            varColor: Fmt.varColor(
              'BOH Hours',
              (s.bohHours - theoBoh).toDouble(),
            ),
          ),
          _micro(),
          _ShiftRow(
            label: 'CPLH',
            target: lockedCPLH.toStringAsFixed(2),
            actual: s.cplh.toStringAsFixed(2),
            variance: Fmt.varDelta(cplhDelta),
            varColor: Fmt.varColor('CPLH', cplhDelta),
          ),
          _micro(),
          _ShiftRow(
            label: 'SPLH',
            target: '\$${lockedSPLH.toStringAsFixed(0)}',
            actual: '\$${s.splh.toStringAsFixed(0)}',
            variance: Fmt.varDollars(splhDelta),
            varColor: Fmt.varColor('SPLH', splhDelta),
          ),
          _GroupBand('OUTCOMES'),
          _ShiftRow(
            label: 'FOH Labor %',
            target: '${lockedFohPct.toStringAsFixed(1)}%',
            actual: '${s.fohLaborPct.toStringAsFixed(1)}%',
            variance: Fmt.varPts(s.fohLaborPct - lockedFohPct),
            varColor: Fmt.varColor('FOH Labor %', s.fohLaborPct - lockedFohPct),
          ),
          _micro(),
          _ShiftRow(
            label: 'BOH Labor %',
            target: '${lockedBohPct.toStringAsFixed(1)}%',
            actual: '${s.bohLaborPct.toStringAsFixed(1)}%',
            variance: Fmt.varPts(s.bohLaborPct - lockedBohPct),
            varColor: Fmt.varColor('BOH Labor %', s.bohLaborPct - lockedBohPct),
          ),
          _micro(),
          _ShiftRow(
            label: 'Total Labor %',
            target: '${s.theoreticalLaborPct.toStringAsFixed(1)}%',
            actual: '${s.totalLaborPct.toStringAsFixed(1)}%',
            variance: Fmt.varPts(s.variancePts),
            varColor: Fmt.varColor('Total Labor %', s.variancePts),
            isBold: true,
          ),
          const SizedBox(height: 10),
          _LeverBadge(lever: s.primaryLever),
        ],
      ),
    );
  }

  Widget _micro() => Container(
    height: 1,
    color: AppColors.borderSubtle.withValues(alpha: 0.5),
  );
}

class _ProjectedShiftDetail extends StatelessWidget {
  final ShiftRecord shift;
  final bool isOpen;
  const _ProjectedShiftDetail({required this.shift, this.isOpen = false});

  @override
  Widget build(BuildContext context) {
    final headerLabel = isOpen ? 'PLAN CONTEXT' : 'PROJECTED';
    final statusColor = isOpen ? AppColors.sunsetDark : AppColors.textMuted;

    // Daypart label is now rendered by StickyDaypartLabelDelegate.
    // This widget starts directly with the detail rows.
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 10, 14, 13),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                flex: 4,
                child: Text(
                  'METRIC',
                  style: AppTextStyles.mono8(color: AppColors.textMuted),
                ),
              ),
              Expanded(
                flex: 6,
                child: Text(
                  headerLabel,
                  style: AppTextStyles.mono8(color: statusColor),
                  textAlign: TextAlign.right,
                ),
              ),
            ],
          ),
          Container(height: 1, color: AppColors.borderSubtle),
          _GroupBand('CONDITIONS'),
          _ProjectedMetricRow(
            label: 'Covers',
            value: '${shift.forecastCovers} (plan)',
            valueColor: AppColors.sunsetDark,
          ),
          _micro(),
          Builder(
            builder: (ctx) {
              final profile = ctx
                  .watch<ActiveTargetProfileNotifier?>()
                  ?.profile;
              final wage =
                  profile?.targetBlendedWage ??
                  shift.snapshotBlendedWage ??
                  shift.blendedWage;
              return _ProjectedMetricRow(
                label: 'Blended Wage',
                value: '\$${wage.toStringAsFixed(2)} (plan)',
                valueColor: AppColors.sunsetDark,
              );
            },
          ),
          _GroupBand('EXECUTION'),
          _ProjectedMetricRow(
            label: 'FOH Hours',
            value: '${shift.fohHours} (plan)',
            valueColor: AppColors.sunsetDark,
          ),
          _micro(),
          _ProjectedMetricRow(
            label: 'BOH Hours',
            value: '${shift.bohHours} (plan)',
            valueColor: AppColors.sunsetDark,
          ),
          _GroupBand('OUTCOMES'),
          Builder(
            builder: (ctx) {
              final profile = ctx
                  .watch<ActiveTargetProfileNotifier?>()
                  ?.profile;
              final theoPct =
                  profile?.theoreticalLaborPct ?? shift.theoreticalLaborPct;
              return _ProjectedMetricRow(
                label: 'Labor %',
                value: '${theoPct.toStringAsFixed(1)}% (theoretical)',
                valueColor: AppColors.sunsetDark,
              );
            },
          ),
          const SizedBox(height: 12),
          Builder(
            builder: (ctx) {
              final wd = ctx.read<WeekDataNotifier>().weekData!;
              final projColor = wd.projVariancePts > 0
                  ? AppColors.negative
                  : AppColors.positive;
              return RichText(
                text: TextSpan(
                  style: AppTextStyles.mono10(color: AppColors.textMuted),
                  children: [
                    const TextSpan(text: 'Week ends at '),
                    TextSpan(
                      text: '${wd.projActualLaborPct.toStringAsFixed(1)}%',
                      style: AppTextStyles.mono10(color: projColor),
                    ),
                    const TextSpan(text: '  ->  gap '),
                    TextSpan(
                      text:
                          '\$${wd.projDollarGapWeekly.abs().toStringAsFixed(0)}',
                      style: AppTextStyles.mono10(color: projColor),
                    ),
                  ],
                ),
              );
            },
          ),
          const SizedBox(height: 4),
          Text(
            isOpen
                ? 'Live shift in progress. Finalizes on close.'
                : 'Projected from weekly plan. Actuals populate when shift closes.',
            style: AppTextStyles.mono8(
              color: isOpen ? AppColors.sunsetDark : AppColors.textMuted,
            ),
          ),
        ],
      ),
    );
  }

  Widget _micro() => Container(
    height: 1,
    color: AppColors.borderSubtle.withValues(alpha: 0.5),
  );
}

class _ProjectedMetricRow extends StatelessWidget {
  final String label;
  final String value;
  final Color valueColor;

  const _ProjectedMetricRow({
    required this.label,
    required this.value,
    required this.valueColor,
  });

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 7),
      child: Row(
        children: [
          Expanded(
            flex: 4,
            child: Text(
              label,
              style: AppTextStyles.body13(color: AppColors.textSecondary),
            ),
          ),
          Expanded(
            flex: 6,
            child: Text(
              value,
              style: AppTextStyles.mono12(color: valueColor),
              textAlign: TextAlign.right,
            ),
          ),
        ],
      ),
    );
  }
}

class _ShiftRow extends StatelessWidget {
  final String label;
  final String target;
  final String actual;
  final String variance;
  final Color varColor;
  final bool isHeader;
  final bool isBold;

  const _ShiftRow({
    required this.label,
    required this.target,
    required this.actual,
    required this.variance,
    this.varColor = AppColors.textMuted,
    this.isHeader = false,
    this.isBold = false,
  });

  const _ShiftRow.header()
    : this(
        label: 'METRIC',
        target: 'TARGET',
        actual: 'ACTUAL',
        variance: 'VAR',
        isHeader: true,
      );

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 7),
      child: Row(
        children: [
          Expanded(
            flex: 4,
            child: Text(
              label,
              style: isHeader
                  ? AppTextStyles.mono8(color: AppColors.textMuted)
                  : (isBold
                        ? AppTextStyles.mono12(
                            color: AppColors.textPrimary,
                            weight: FontWeight.w700,
                          )
                        : AppTextStyles.body13(color: AppColors.textSecondary)),
            ),
          ),
          Expanded(
            flex: 3,
            child: Text(
              target,
              style: isHeader
                  ? AppTextStyles.mono8(color: AppColors.textMuted)
                  : AppTextStyles.mono8(color: AppColors.textMuted),
              textAlign: TextAlign.right,
            ),
          ),
          Expanded(
            flex: 3,
            child: Text(
              actual,
              style: isHeader
                  ? AppTextStyles.mono8(color: AppColors.textMuted)
                  : AppTextStyles.mono11(color: AppColors.textPrimary),
              textAlign: TextAlign.right,
            ),
          ),
          Expanded(
            flex: 3,
            child: Text(
              variance,
              style: isHeader
                  ? AppTextStyles.mono8(color: AppColors.textMuted)
                  : AppTextStyles.mono12(
                      color: varColor,
                      weight: FontWeight.w700,
                    ),
              textAlign: TextAlign.right,
            ),
          ),
        ],
      ),
    );
  }
}

// ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ Lever badge (inside expanded closed shift) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚ÂÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬

