class _ProjectedTotalRow extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final wd = context.read<WeekDataNotifier>().weekData!;
    final isOver = wd.projVariancePts > 0;
    final ptColor = isOver ? AppColors.negative : AppColors.positive;
    final ptSign = isOver ? '+' : '-';

    return Container(
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [AppColors.backgroundSurface, AppColors.shimmer],
        ),
        border: Border(
          top: BorderSide(
            color: AppColors.sunset.withValues(alpha: 0.15),
            width: 1,
          ),
        ),
      ),
      padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 14),
      child: Row(
        children: [
          // Same flex:4 as day rows' label column
          Expanded(
            flex: 4,
            child: Text(
              'PROJ TOTAL',
              style: AppTextStyles.mono14(
                  color: AppColors.textPrimary,
                  weight: FontWeight.w700),
            ),
          ),
          // Same flex:3 as day rows' labor % column — stacks target + proj
          Expanded(
            flex: 3,
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Column(
                  crossAxisAlignment: CrossAxisAlignment.end,
                  children: [
                    Text(
                      '${wd.projTargetLaborPct.toStringAsFixed(1)}%',
                      style: AppTextStyles.mono10(color: AppColors.textMuted),
                    ),
                    Text('TARGET',
                        style: AppTextStyles.mono7(color: AppColors.textMuted)),
                  ],
                ),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.end,
                  children: [
                    Text(
                      '${wd.projActualLaborPct.toStringAsFixed(1)}%',
                      style: AppTextStyles.mono12(color: ptColor),
                    ),
                    Text('PROJ',
                        style: AppTextStyles.mono7(color: AppColors.textMuted)),
                  ],
                ),
              ],
            ),
          ),
          // Same flex:3 as day rows' variance pts column
          Expanded(
            flex: 3,
            child: Text(
              '$ptSign${wd.projVariancePts.abs().toStringAsFixed(1)} pts',
              style: AppTextStyles.mono12(
                color: ptColor,
                weight: FontWeight.w700,
              ),
              textAlign: TextAlign.right,
            ),
          ),
          // Match the chevron space in day rows
          const Padding(
            padding: EdgeInsets.only(left: 4),
            child: SizedBox(width: 20),
          ),
        ],
      ),
    );
  }
}

